USE market_db;
GO

-- ========================================================================================
-- ไฟล์: data.sql (ชุดข้อมูลจำลอง Mock Data สำหรับระบบการจองและเช่าพื้นที่ตลาดนัด - หัวข้อ 27)
-- DBMS: Microsoft SQL Server (T-SQL) | อ้างอิงตาม Schema v0.1
-- ข้อกำหนด:
--   1. ตารางหลัก (leases, utility_charges, payments) มีมากกว่า 500 แถว
--   2. ตารางประกอบ (stalls, merchants, market_days, staff, fine_logs) มี 20-50 แถว
--   3. ตาราง payments ไม่มีคอลัมน์ fine_id (ใช้ payment_type = 'fine' คู่กับ lease_id)
--   4. ตาราง utility_charges ไม่ INSERT คอลัมน์คำนวณ charge_amount
--   5. สัญญาที่ยกเลิก (cancelled) มีการบันทึกคืนเฉพาะมัดจำ (deposit_refund) ไม่คืนค่าเช่า
-- ========================================================================================

SET NOCOUNT ON;

-- ========================================================================================
-- 1. ตาราง stall_zones (5 แถว)
-- ========================================================================================
SET IDENTITY_INSERT stall_zones ON;
SET IDENTITY_INSERT stall_zones OFF;
GO

-- ========================================================================================
-- 2. ตาราง stalls (50 แผง: available 47 แผง, maintenance 3 แผง)
-- ========================================================================================
SET IDENTITY_INSERT stalls ON;
SET IDENTITY_INSERT stalls OFF;
GO

-- ========================================================================================
-- 3. ตาราง merchants (40 แถว)
-- ========================================================================================
SET IDENTITY_INSERT merchants ON;
SET IDENTITY_INSERT merchants OFF;
GO

-- ========================================================================================
-- 4. ตาราง market_days (51 แถว: อดีต 45 วัน [เปิด 42, ปิดปรับปรุง 3] + อนาคต 6 วันสำหรับสาธิตการจอง)
-- ========================================================================================
SET IDENTITY_INSERT market_days ON;
-- วันตลาดในอนาคต (พ.ย.-ธ.ค. 2569) เปิดรับจองแต่ยังไม่มีสัญญา ไว้สาธิต sp_reserve_stall / sp_record_utility / sp_cancel_lease
SET IDENTITY_INSERT market_days OFF;
GO

-- ========================================================================================
-- 5. ตาราง staff (20 แถว)
-- ========================================================================================
SET IDENTITY_INSERT staff ON;
SET IDENTITY_INSERT staff OFF;
GO

-- ========================================================================================
-- 6. ตาราง leases (ตารางหลัก 540+ แถว)
-- ========================================================================================
SET IDENTITY_INSERT leases ON;
SET IDENTITY_INSERT leases OFF;
GO

-- ========================================================================================
-- 7. ตาราง utility_charges (1,000+ แถว: แยก water และ electricity, ไม่ใส่ charge_amount)
-- ========================================================================================
SET IDENTITY_INSERT utility_charges ON;
SET IDENTITY_INSERT utility_charges OFF;
GO

-- ========================================================================================
-- 8. ตาราง fine_logs (30 แถว)
-- ========================================================================================
SET IDENTITY_INSERT fine_logs ON;
SET IDENTITY_INSERT fine_logs OFF;
GO

-- ========================================================================================
-- 9. ตาราง payments (1,600+ แถว: ไม่มี fine_id, ยกเลิกสัญญาคืนเฉพาะ deposit_refund)
-- ========================================================================================
SET IDENTITY_INSERT payments ON;
SET IDENTITY_INSERT payments OFF;
GO

-- สรุปผลการสร้างข้อมูล: leases = 575 แถว, utility_charges = 1126 แถว, fine_logs = 30 แถว, payments = 1755 แถว